import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const role = localStorage.getItem("role"); // 'admin' or 'user'

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);

    try {
      const response = await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      setName('');
      setImage(null);
      setShowForm(false);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.headerRow}>
        <h1 style={styles.mainTitle}>🗂️ Categories</h1>
        <input
          type="text"
          placeholder="🔍 Search categories..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={styles.searchInput}
        />
        {role === "admin" && (
          <button style={styles.addBtn} onClick={() => setShowForm(true)}>+ Add Category</button>
        )}
      </div>
      <div style={styles.grid}>
        {categories
          .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
          .map((cat) => (
            <div
              key={cat._id}
              style={styles.card}
              className="modern-category-card"
            >
              <div style={styles.cardImageWrap}>
                <img
                  src={`http://localhost:5000/uploads/${cat.image}`}
                  alt={cat.name}
                  style={styles.image}
                />
                <div style={styles.overlay}></div>
                <div style={styles.cardTitleWrap}>
                  <h3 style={styles.cardTitle}>{cat.name}</h3>
                </div>
              </div>
            </div>
          ))}
      </div>
      {showForm && (
        <div style={styles.modalOverlay} onClick={() => setShowForm(false)}>
          <div style={styles.modalBox} onClick={e => e.stopPropagation()}>
            <h2 style={styles.formTitle}>✨ Add Category</h2>
            <form onSubmit={handleAddCategory} encType="multipart/form-data" style={styles.form}>
              <input
                type="text"
                placeholder="Enter Category Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                style={styles.input}
              />
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setImage(e.target.files[0])}
                required
                style={styles.input}
              />
              <div style={{ display: 'flex', gap: 12, marginTop: 8 }}>
                <button type="submit" style={styles.button}>➕ Add</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowForm(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(to right, #181c24, #232a36)",
    fontFamily: "'Segoe UI', sans-serif",
    padding: "0 0 60px 0",
  },
  headerRow: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 16,
    maxWidth: 1200,
    margin: "0 auto 32px auto",
    padding: "40px 16px 0 16px",
  },
  mainTitle: {
    fontSize: "32px",
    color: "#60a5fa",
    fontWeight: 800,
    margin: 0,
  },
  searchInput: {
    background: "#232a36",
    color: "#e0eafc",
    borderRadius: "10px",
    padding: "14px 20px",
    width: "320px",
    height: "40px",
    border: "1.5px solid #374151",
    fontSize: "16px",
    outline: "none",
    boxShadow: "0 2px 8px rgba(0,0,0,0.12)",
    fontFamily: "inherit"
  },
  addBtn: {
    background: "linear-gradient(to right, #2563eb, #22d3ee)",
    color: "#fff",
    border: "none",
    borderRadius: "10px",
    padding: "12px 28px",
    fontWeight: 700,
    fontSize: "17px",
    cursor: "pointer",
    boxShadow: "0 4px 16px rgba(96,165,250,0.10)",
    marginLeft: 12,
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
    gap: "36px",
    maxWidth: 1200,
    margin: "0 auto",
    padding: "0 16px",
  },
  card: {
    background: "#232a36",
    borderRadius: "22px",
    boxShadow: "0 8px 32px rgba(96,165,250,0.13)",
    overflow: "hidden",
    position: "relative",
    transition: "transform 0.18s cubic-bezier(.4,2,.6,1), box-shadow 0.18s cubic-bezier(.4,2,.6,1)",
    cursor: "pointer",
    border: "1.5px solid #374151",
    minHeight: 220,
    display: "flex",
    flexDirection: "column",
    justifyContent: "flex-end",
  },
  cardImageWrap: {
    position: "relative",
    width: "100%",
    height: 180,
    overflow: "hidden",
    display: "flex",
    alignItems: "flex-end",
    justifyContent: "center",
  },
  image: {
    width: "100%",
    height: "100%",
    objectFit: "cover",
    borderTopLeftRadius: "22px",
    borderTopRightRadius: "22px",
    filter: "brightness(0.92)",
    transition: "filter 0.2s",
  },
  overlay: {
    position: "absolute",
    left: 0,
    top: 0,
    width: "100%",
    height: "100%",
    background: "linear-gradient(to top, #181c24 60%, rgba(24,28,36,0.0) 100%)",
    opacity: 0.7,
    zIndex: 1,
  },
  cardTitleWrap: {
    position: "absolute",
    left: 0,
    right: 0,
    bottom: 0,
    zIndex: 2,
    padding: "18px 0 14px 0",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "rgba(24,28,36,0.55)",
    borderBottomLeftRadius: "22px",
    borderBottomRightRadius: "22px",
  },
  cardTitle: {
    margin: 0,
    fontSize: "22px",
    color: "#fff",
    fontWeight: 700,
    letterSpacing: 0.5,
    textShadow: "0 2px 8px rgba(24,28,36,0.18)",
  },
  modalOverlay: {
    position: "fixed",
    left: 0,
    top: 0,
    width: "100vw",
    height: "100vh",
    background: "rgba(24,28,36,0.92)",
    zIndex: 9999,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  modalBox: {
    background: "#232a36",
    borderRadius: "18px",
    boxShadow: "0 8px 32px rgba(96,165,250,0.18)",
    padding: "36px 32px 28px 32px",
    minWidth: 320,
    maxWidth: 400,
    width: "100%",
    zIndex: 10000,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  formTitle: {
    fontSize: "22px",
    marginBottom: "20px",
    color: "#60a5fa",
    fontWeight: 700,
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
    width: "100%",
  },
  input: {
    padding: "12px",
    fontSize: "15px",
    borderRadius: "8px",
    border: "1px solid #374151",
    backgroundColor: "#181c24",
    color: "#e0eafc",
  },
  button: {
    padding: "12px 0",
    background: "linear-gradient(to right, #2563eb, #22d3ee)",
    color: "white",
    fontSize: "16px",
    fontWeight: "bold",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "opacity 0.3s ease",
    width: 120,
  },
  cancelBtn: {
    padding: "12px 0",
    background: "#374151",
    color: "#e0eafc",
    fontSize: "16px",
    fontWeight: "bold",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "opacity 0.3s ease",
    width: 120,
  },
};

export default Category;
